// STEP 1 - manual/staging trigger input (sales_vertical_slice step 1).
  // Bounded + test-mode-safe. In prod this is a Webhook / Schedule trigger.
  const staging = {
    country: 'DE',
    hsProduct: '4202.92 / cotton shopping bags',
    buyerCount: 3,
    testMode: true,                         // GATE: nothing reaches a real buyer
    testRecipient: 'demo-inbox@aaziko-test.example'
  };
  // 3 mock inbound signals - each exercises a DIFFERENT Jarvis decision path.
  const rawEvents = [
    { eventId: 'EVT-1001', type: 'NEW_BUYER_SIGNAL', source: 'trade_data_api',
      receivedAt: '2026-09-20T09:00:00Z', sourceMsgId: 'sig-de-cotton-01',
      buyer: { name: 'Nordwind Handels GmbH', country: 'DE', product: 'cotton shopping bags', hs: '4202.92', qty: 20000, unit: 'pcs' } },
    { eventId: 'EVT-1002', type: 'EMAIL_RECEIVED', source: 'zoho_mail',
      receivedAt: '2026-09-21T11:30:00Z', sourceMsgId: 'mail-us-mug-77',
      buyer: { name: 'Blue Ridge Imports LLC', country: 'US', product: 'ceramic mugs', hs: '6912.00', qty: 15000, unit: 'pcs' },
      note: 'Buyer asked us for a quotation 15 days ago; Aaziko has NOT sent it yet.' },
    { eventId: 'EVT-1003', type: 'NEW_BUYER_SIGNAL', source: 'trade_data_api',
      receivedAt: '2026-09-22T08:15:00Z', sourceMsgId: 'sig-uk-led-05',
      buyer: { name: 'Brightwave Retail Ltd', country: 'GB', product: 'LED bulbs', hs: '8539.50', qty: 30000, unit: 'pcs' } }
  ];
  return rawEvents.map(e => ({ json: { staging, event: e } }));

// CORE-01 - validate source, dedup, persist event, historical-vs-live.
  // MOCK dedup in-memory; in prod = Mongo aaziko_jarvis.events, unique index on sourceMsgId.
  const seen = new Set();
  const out = [];
  for (const item of $input.all()) {
    const { staging, event } = item.json;
    const allowedSources = ['trade_data_api', 'zoho_mail', 'order-service', 'logistics'];
    const sourceValid = allowedSources.includes(event.source);
    const duplicate = seen.has(event.sourceMsgId);
    seen.add(event.sourceMsgId);
    const ageDays = (Date.now() - new Date(event.receivedAt).getTime()) / 86400000;
    const mode = ageDays > 30 ? 'HISTORICAL_REPLAY' : 'LIVE';
    out.push({ json: { staging, event, intake: {
      persistedEventId: event.eventId, sourceValid, duplicate, mode,
      persistedAt: new Date().toISOString(), collection: 'aaziko_jarvis.events (MOCK)' } } });
  }
  return out;

// CORE-02 - resolve entity/contact/company/opportunity/current case.
  // Ambiguous matches -> human review. MOCK identity directory.
  const entityDir = {
    'Nordwind Handels GmbH': { entityId: 'ENT-DE-4471', confidence: 0.98 },
    'Blue Ridge Imports LLC': { entityId: 'ENT-US-2210', confidence: 0.95 },
    'Brightwave Retail Ltd': { entityId: 'ENT-GB-8830', confidence: 0.71 }
  };
  return $input.all().map(item => {
    const j = item.json; const b = j.event.buyer;
    const match = entityDir[b.name] || { entityId: null, confidence: 0 };
    const ambiguous = match.confidence < 0.5;
    const caseId = match.entityId ? ('CASE-' + match.entityId + '-' + b.hs) : null;
    return { json: Object.assign({}, j, { resolution: {
      entityId: match.entityId, matchConfidence: match.confidence, ambiguous, caseId,
      caseType: 'BUYER_OPPORTUNITY', route: ambiguous ? 'HUMAN_REVIEW' : 'CONTINUE' } }) };
  });

// CORE-03 - retrieve ONLY relevant authorized evidence: facts + sourceRefs + freshness
  // + unknowns + conflicts. MOCK stores; in prod = read-only HTTP APIs + query templates.
  const crmHistory = {
    'ENT-DE-4471': { lastContact: '2026-06-10', openQuestions: [], aazikoOwes: null, suppressed: false },
    'ENT-US-2210': { lastContact: '2026-09-06', openQuestions: ['buyer awaiting our quotation'],
      aazikoOwes: { what: 'send quotation', promisedOn: '2026-09-06', done: false }, suppressed: false },
    'ENT-GB-8830': { lastContact: null, openQuestions: [], aazikoOwes: null, suppressed: false }
  };
  const supplyIntel = {
    '4202.92': { indianSupply: true, sampleSupplier: 'Rajkot Textiles', moq: 5000, unknowns: ['exact FOB price'] },
    '6912.00': { indianSupply: true, sampleSupplier: 'Morbi Ceramics', moq: 10000, unknowns: ['exact FOB price'] },
    '8539.50': { indianSupply: true, sampleSupplier: 'Noida Lighting', moq: 10000, unknowns: ['exact FOB price', 'BIS cert status'] }
  };
  const tariffIntel = {
    'DE-4202.92': { dutyPct: 9.7, source: 'macmap_tariff', asOf: '2026-08-01' },
    'US-6912.00': { dutyPct: 9.8, source: 'macmap_tariff', asOf: '2026-08-01' },
    'GB-8539.50': { dutyPct: 3.7, source: 'macmap_tariff', asOf: '2026-08-01' }
  };
  return $input.all().map(item => {
    const j = item.json; const b = j.event.buyer;
    const crm = crmHistory[j.resolution.entityId] || {};
    const supply = supplyIntel[b.hs] || {};
    const tariff = tariffIntel[b.country + '-' + b.hs] || {};
    return { json: Object.assign({}, j, { context: {
      facts: { buyer: b, crm, supply, tariff },
      sourceRefs: ['crm-service', 'vendor-service', 'macmap_tariff'],
      freshness: { crm: crm.lastContact || 'none', tariffAsOf: tariff.asOf || 'unknown' },
      unknowns: supply.unknowns || ['supply unknown'],
      conflicts: [], accessLimitations: 'read-only; no raw price fabricated' } }) };
  });

// Deterministic commercial comparison (prompt: use CODE for calculations, not AI).
  // UNKNOWN inputs stay UNKNOWN - never invent a price/saving (ai_communication_policy).
  return $input.all().map(item => {
    const j = item.json; const t = j.context.facts.tariff || {};
    const dutyPct = (typeof t.dutyPct === 'number') ? t.dutyPct : 'UNKNOWN';
    return { json: Object.assign({}, j, { commercial: {
      fobPrice: 'UNKNOWN - NEEDS VERIFICATION',
      dutyPct,
      landedCost: 'UNKNOWN - NEEDS VERIFICATION (FOB not confirmed)',
      note: 'Deterministic: no savings/price fabricated when inputs missing.' } }) };
  });

// COMM-01 - decide next action. Sending is only ONE option.
  // communication_rules: age triggers a REVIEW, never a blind message.
  return $input.all().map(item => {
    const j = item.json; const crm = j.context.facts.crm || {};
    let decision, reason;
    if (crm.suppressed) { decision = 'SUPPRESS'; reason = 'recipient suppressed'; }
    else if (j.resolution.ambiguous) { decision = 'HUMAN_REVIEW'; reason = 'identity ambiguous'; }
    else if (crm.aazikoOwes && crm.aazikoOwes.done === false) {
      decision = 'CREATE_INTERNAL_TASK';
      reason = 'Aaziko owes "' + crm.aazikoOwes.what + '" since ' + crm.aazikoOwes.promisedOn +
        ' - do NOT chase buyer; finish our part first.';
    } else { decision = 'CONTACT'; reason = 'open opportunity, no unfinished Aaziko commitment'; }
    return { json: Object.assign({}, j, { decision, decisionReason: reason }) };
  });

// COMM-02 - draft from a BOUNDED evidence packet (mock AI). Keeps SAFE_TO_SAY / DO_NOT_CLAIM.
  // For HS 8539.50 we deliberately let the "AI" hallucinate a price so QA can catch & block it.
  return $input.all().map(item => {
    const j = item.json; const b = j.context.facts.buyer;
    const safeToSay = ['Aaziko can support sourcing from qualified Indian manufacturers',
      'We can coordinate inspection, logistics and export documentation'];
    const doNotClaim = ['price', 'guaranteed MOQ', 'duty savings', 'delivery date'];
    let body = 'Hello ' + b.name + ' team,\n\n' +
      'We understand you are looking for ' + b.product + ' (approx ' + b.qty + ' ' + b.unit + '). ' +
      'Aaziko can help source this from qualified Indian suppliers and manage inspection, logistics and export documentation.\n\n' +
      'Could you confirm your target specification and timeline so we can prepare a supported quotation?\n\n' +
      'Regards,\nAaziko Jarvis Communicator (AI assistant). Your Aaziko account manager remains available.';
    let injectedClaim = null;
    if (b.hs === '8539.50') {
      injectedClaim = 'We can offer the best price of $1.20 per unit with 40% duty savings.';
      body += '\n\nP.S. ' + injectedClaim;
    }
    return { json: Object.assign({}, j, { draft: {
      to: j.staging.testRecipient, subject: 'Aaziko - ' + b.product + ' sourcing',
      body, safeToSay, doNotClaim, injectedClaim } }) };
  });

// Independent QA - identity/product/qty/claims/confidentiality/recipient checks.
  // Critical acceptance target: block unsupported claims BEFORE any send.
  return $input.all().map(item => {
    const j = item.json; const d = j.draft; const issues = [];
    const forbidden = /\$\s?\d|best price|duty savings|guaranteed|\bMOQ\b\s*\d/i;
    if (forbidden.test(d.body)) issues.push('Unsupported commercial claim (price/savings not verified)');
    if (!d.body.includes(j.context.facts.buyer.product)) issues.push('Product mismatch');
    if (!d.to || d.to.indexOf('test') === -1) issues.push('Recipient is not the approved TEST inbox');
    const qaPassed = issues.length === 0;
    return { json: Object.assign({}, j, { qa: { qaPassed, issues, checkedAt: new Date().toISOString() } }) };
  });

// ACTION-01 - in prod this is a Wait-for-webhook approval (WhatsApp/Slack/Form).
  // Here we simulate an explicit human approval, recorded to the action ledger.
  return $input.all().map(item => {
    const j = item.json;
    return { json: Object.assign({}, j, { approval: {
      approved: true, approvedBy: 'demo.reviewer@aaziko (SIMULATED)',
      approvedAt: new Date().toISOString(),
      note: 'Real flow PAUSES here for a human; nothing sends without this.' } }) };
  });

// ACTION-01 - recheck latest case state immediately before send + build idempotency key.
  function hash(s) { let h = 0; for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; } return ('00000000' + (h >>> 0).toString(16)).slice(-8); }
  return $input.all().map(item => {
    const j = item.json;
    const payload = JSON.stringify({ to: j.draft.to, subject: j.draft.subject, body: j.draft.body });
    return { json: Object.assign({}, j, { execGuard: {
      caseRechecked: true, stillOpen: true,
      idempotencyKey: 'ACT-' + j.resolution.caseId + '-' + hash(payload), payloadHash: hash(payload) } }) };
  });

// ACTION-01 - SIMULATED send. No real provider call. TEST recipient only.
  // A timeout here = UNKNOWN (reconcile), never a blind retry.
  return $input.all().map(item => {
    const j = item.json;
    return { json: Object.assign({}, j, { send: {
      channel: 'email', provider: 'MOCK (no real send)', to: j.draft.to, testMode: j.staging.testMode,
      actionState: 'SUCCEEDED', messageRef: 'MSG-' + j.execGuard.idempotencyKey, sentAt: new Date().toISOString(),
      ledger: 'aaziko_jarvis.actions (MOCK): PROPOSED->APPROVED->EXECUTING->SUCCEEDED' } }) };
  });

// CRM-01 - record activity in owning CRM + set waiting party + schedule NEXT REVIEW
  // (not "send in 7 days" - a REVIEW that re-decides).
  return $input.all().map(item => {
    const j = item.json;
    const nextReviewAt = new Date(Date.now() + 7 * 86400000).toISOString();
    return { json: Object.assign({}, j, { crm: {
      activityLogged: true, waitingOn: 'BUYER',
      communicationHistory: 'aaziko_jarvis.communication_history (MOCK): SENT',
      review: { reviewId: 'REV-' + j.resolution.caseId, nextReviewAt,
        rule: 'On review: who owes next action? new replies? still open? suppressed? evidence fresh?' },
      outcome: 'sent (awaiting reply)' } }) };
  });

// QA blocked the draft -> route to human review. NOTHING is sent.
  return $input.all().map(item => {
    const j = item.json;
    return { json: Object.assign({}, j, { humanReview: {
      queued: true, reason: 'QA blocked unsupported/unsafe content', issues: j.qa.issues,
      assignedTo: 'sales.reviewer@aaziko', sendBlocked: true,
      outcome: 'BLOCKED_BY_QA (no send) - the safety guarantee in action' } }) };
  });

// Decision != CONTACT -> internal handling. For "Aaziko owes work" we create an internal
  // task instead of messaging the buyer (communication_rules example).
  return $input.all().map(item => {
    const j = item.json; const owes = (j.context.facts.crm || {}).aazikoOwes;
    return { json: Object.assign({}, j, { internal: {
      action: j.decision,
      task: owes ? { taskId: 'TASK-' + j.resolution.caseId, type: 'QUOTATION', owner: 'sales',
        due: new Date(Date.now() + 2 * 86400000).toISOString(), reason: j.decisionReason } : null,
      buyerContacted: false,
      outcome: 'INTERNAL_TASK_CREATED (buyer NOT chased) - Jarvis does our part first' } }) };
  });

// Collect all branches into one clean, pitch-ready audit trace.
  const rows = $input.all().map(item => {
    const j = item.json; const b = j.event.buyer;
    const outcome = (j.crm && j.crm.outcome) || (j.humanReview && j.humanReview.outcome) ||
      (j.internal && j.internal.outcome) || 'n/a';
    return {
      caseId: j.resolution.caseId, buyer: b.name, country: b.country, product: b.product,
      intakeMode: j.intake.mode, decision: j.decision, decisionReason: j.decisionReason,
      qa: j.qa ? (j.qa.qaPassed ? 'PASS' : 'BLOCK (' + j.qa.issues.join('; ') + ')') : 'n/a (no draft)',
      sent: j.send ? j.send.actionState : 'NOT SENT',
      nextReview: j.crm ? j.crm.review.nextReviewAt : 'n/a', outcome
    };
  });
  return [{ json: {
    demo: 'Aaziko ATES Jarvis - Sales Vertical Slice (n8n feasibility)',
    proves: [
      'Event intake + dedup + historical-vs-live',
      'Identity/case resolution (ambiguous -> human)',
      'Bounded read-only context (unknowns stay UNKNOWN)',
      'Deterministic commercial math (no invented price)',
      'Decision engine: send is only ONE option',
      'Aaziko-owes-work -> internal task, NOT chase buyer',
      'Independent QA blocks unsupported claims before send',
      'Human approval gate + recheck + idempotency',
      'Simulated send to TEST recipient only (zero real sends)',
      'CRM activity + next-REVIEW (not blind resend)',
      'Full audit trace'
    ],
    cases: rows
  } }];
